mapper.select:
/*selectMasterMdCmSellerCmpyChoicePopList*/ SELECT /*+FULL(Y) PARALLEL(Y 4)*/ Y.COM_CODE AS AGENT, --[0] Y.COM_NAME_LOC AS COM_NAME_LOC, --[1] Y.IRS_NO AS IRS_NO, --[2] Y.INDUSTRY_TYPE AS INDUSTRY_TYPE, --[3] Y.BUSINESS_ITEMS AS BUSINESS_ITEMS, --[4] (SELECT COUNT(0) FROM ICOMCOD1 WHERE TYPE = 'HUB' AND FLAG ='Y' AND CODE =Y.COM_CODE) AS LOGISTICS_CENTER_CNT FROM ICOMCMPY Y WHERE Y.COM_CODE IN (SELECT A.AGENT FROM ICOMCQDT A WHERE (A.BUYER, A.BUYER_ITEM_NO) IN (SELECT B.BUYER, B.BUYER_ITEM_NO FROM ICOMBYIT B WHERE 1=1
AND B.CATEGORY_NO = #{st_category_no}
) AND A.STATUS = 'C' AND A.BUYER = UPPER(#{st_buyer} )
AND A.AGENT = UPPER(#{st_agent})
) AND Y.BUSINESS_COND = 'S'
AND Y.CREDIT_STATUS <> 'N'
ORDER BY Y.COM_NAME_LOC

/*selectMasterMdCmSellerCmpyChoicePopOldList*/ SELECT X.AGENT AS AGENT, --[0] Y.COM_NAME_LOC AS COM_NAME_LOC, --[1] Y.IRS_NO AS IRS_NO, --[2] Y.INDUSTRY_TYPE AS INDUSTRY_TYPE, --[3] Y.BUSINESS_ITEMS AS BUSINESS_ITEMS, --[4] (SELECT COUNT(0) FROM ICOMCOD1 WHERE TYPE = 'HUB' AND FLAG ='Y' AND CODE =X.AGENT) AS LOGISTICS_CENTER_CNT FROM (SELECT DISTINCT AGENT FROM ICOMCQDT WHERE BUYER = UPPER(#{st_buyer}) AND STATUS = 'C'
AND AGENT LIKE UPPER(#{st_agent_code}||'%')
) X, ICOMCMPY Y WHERE X.AGENT = Y.COM_CODE AND Y.STATUS IN ('C','R') AND Y.BUSINESS_COND = 'S'
AND Y.COM_NAME_LOC LIKE '%'||#{st_agent_name}||'%'
AND Y.CREDIT_STATUS <> 'N'
ORDER BY Y.COM_NAME_LOC
